mapper.insert:
insert into room (
	room_no, room_owner, room_type
)
values( 
	#{roomNo} , #{roomOwner} , #{roomType}
)

insert into room_user (
	room_user_no, room_no, account_no
)
values( 
	#{roomUserNo} , #{roomNo} , #{accountNo}
)

mapper.select:
select 	account_no from room_user
 where 	room_no = #{roomNo}
order by account_no asc

mapper.update:
update	room
   set	last_employee_read_time = systimestamp
 where	room_no = #{roomNo}

update	room_user
   set	last_read_time = systimestamp
 where	room_no = #{roomNo}
   and	account_no = #{accountNo}

mapper.delete:
delete	room_user
where	room_no = #{roomNo}
  and	account_no = #{accountNo}
